    "2468bd66": {"text":"Farinha ruim, feita em silêncio, ainda é farinha.","hash":"h1-69685603"},
    "246c8b5a": {"text":"Capital do reino","hash":"h1-2e5112f8"},
    "2470dbde": {"forms":{"select":"value","param":"hasCompanies","cases":{"none":"~150 lanças: {money:15} agora, {money:upkeep} por estação enquanto a hoste estiver levantada.","some":{"select":"plural","param":"count","cases":{"one":"~150 lanças: {money:15} agora, {money:upkeep} por estação enquanto a hoste estiver levantada. ({count} companhia sob seu estandarte)","other":"~150 lanças: {money:15} agora, {money:upkeep} por estação enquanto a hoste estiver levantada. ({count} companhias sob seu estandarte)"}},"other":"~150 lanças: {money:15} agora, {money:upkeep} por estação enquanto a hoste estiver levantada."}},"hash":"h1-479d5ecf"},
