    "7f30ae0c": {"text":"sem fim fixo","hash":"h1-132eae07"},
    "7f3da553": {"text":"Seu nome sobre sua própria porta.","hash":"h1-dc4e9d92"},
    "7f46b3e2": {"text":"Compaixão acima da convenção","hash":"h1-82f28287"},
    "7f4dfc69": {"text":"Manter no serviço","hash":"h1-a30ba2a4"},
    "7f4fcc95": {"text":"Iniciar pesquisa","hash":"h1-3316d17f"},
