    "7f58522d": {"text":"~150 lanças: {money:15} agora, {money:upkeep} por estação enquanto a hoste estiver levantada.","hash":"h1-a9f507c1"},
    "7f585bf0": {"text":"{icon} {unit} ×{count} — ataque {attack}, defesa {defense}","hash":"h1-3ed00af0"},
