    "832690f1": {"text":"Renovar por mais um ano. ({money:8})","hash":"h1-b37b7252"},
    "832ca164": {"text":"A contagem antiga sustenta sua leitura, e este pagamento é dispensado.","hash":"h1-ffc14a4e"},
    "833e8d4a": {"text":"{house}: cargo no Conselho — {office}.","hash":"h1-18c82c50"},
