    "9d54e46e": {"forms":{"select":"value","param":"case","cases":{"Son_f":"👶 Seu filho {parent} tem uma filha, {baby}.","Son_m":"👶 Seu filho {parent} tem um filho, {baby}.","Daughter_f":"👶 Sua filha {parent} tem uma filha, {baby}.","Daughter_m":"👶 Sua filha {parent} tem um filho, {baby}.","Brother_f":"👶 Seu irmão {parent} tem uma filha, {baby}.","Brother_m":"👶 Seu irmão {parent} tem um filho, {baby}.","Sister_f":"👶 Sua irmã {parent} tem uma filha, {baby}.","Sister_m":"👶 Sua irmã {parent} tem um filho, {baby}.","other":"👶 Seu parente {parent} tem um filho, {baby}."}},"hash":"h1-b652e52c"},
