    "dc229c0b": {"text":"💍 {name} entra na sua casa como sua quinta esposa.","hash":"h1-c1930d21"},
    "dc235e96": {"text":"Filha da taberneira","hash":"h1-509c206a"},
    "dc2501e6": {"text":"Uma batalha contra os rebeldes em {county} termina com {winner} dominando o campo.","hash":"h1-d6d874a0"},
