    "e24417f7": {"text":"Ver as construções de {settlement}","hash":"h1-783b47a1"},
    "e245f381": {"text":"householdStandard:","hash":"h1-3280c4ab"},
    "e2620e71": {"text":"Ervas e amuletos não bastaram. A criança se foi.","hash":"h1-0d5cbf90"},
