    "e2fce120": {"text":"tem um papel não suportado.","hash":"h1-1381d5eb"},
    "e2fd1b38": {"text":"Apostar no trigo — mais rico, mais arriscado.","hash":"h1-3dba9773"},
    "e30241e6": {"text":"Maturidade","hash":"h1-88977fd6"},
