    "e679b79c": {"text":"Ver o que ele carrega.","hash":"h1-c497d414"},
    "e67b4939": {"text":"Ser condenado por uma trama contra a autoridade legítima.","hash":"h1-49240ed1"},
    "e68435a4": {"text":"Guerra pela deserção","hash":"h1-3899d1f0"},
    "e688064f": {"text":"Região de criação de cavalos","hash":"h1-ecc30645"},
    "e68d5825": {"text":"Valor (menor–maior)","hash":"h1-cbf2a440"},
