    "ef9a9f78": {"forms":{"select":"value","param":"action","cases":{"arrest":"Levado sob custódia","arrest_failed":"Resistiu à prisão","expired":"Libertado ao fim da custódia","escape":"Fugiu da custódia","release":"Libertado","pardon":"Perdoado e libertado","fine":"Multado e libertado","penance":"Sentenciado a penitência pública","imprisonment":"Sentenciado à prisão","exile":"Exilado","forfeiture":"Títulos e terras confiscados","monastic_exile":"Sentenciado ao exílio monástico","blinding_deposition":"Cegado e deposto","diya":"Compensação de sangue aceita","qisas":"Executado sob qisas","execution":"Executado","ransom":"Resgatado e libertado","other":"Libertado"}},"hash":"h1-8889e733"},
    "ef9cc108": {"text":"A rixa ganha fôlego novo — com seu nome enredado nela.","hash":"h1-29a0774a"},
